// Magic item catalog (Player's Guide, Chapter 5: Magic Items), extracted from
// the item descriptions in the rules reference. Magic items are optional at
// 1st level (a GM may grant them); add any to your sheet.

export type Rarity = 'common' | 'uncommon' | 'rare' | 'very rare' | 'legendary'

export interface MagicItem {
  id: string
  name: string
  type: string
  rarity: Rarity
  attunement: boolean
  text: string
}

export const MAGIC_ITEMS: MagicItem[] = [{"id":"amulet-of-health","name":"Amulet of Health","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) Your CON score is 19 while you carry this amulet. It has no effect on you if your CON is already 19 or higher. 162 PLAYER'S GUIDE"},{"id":"amulet-of-proof-against-detection-and-location","name":"Amulet of Proof Against Detection and Location","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While carrying this amulet, you are hidden from divination magic. You can’t be targeted by spells from the divination school or perceived through magical scrying sensors."},{"id":"animated-shield","name":"Animated Shield","type":"Armor (Shield)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While wielding this shield, you can speak its command word as a bonus action to cause it to animate. The shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free."},{"id":"anklets-of-alacrity","name":"Anklets of Alacrity","type":"Wondrous Item","rarity":"common","attunement":false,"text":"50 gp This pair of light silver anklets look like a running cat chasing a swallow in flight. When you roll initiative while wearing the anklets, you can add your PB to your initiative. You can’t use this property if you are surprised."},{"id":"apparatus-of-the-crab","name":"Apparatus of the Crab","type":"Wondrous Item","rarity":"legendary","attunement":false,"text":"This item first appears to be a Large sealed iron barrel weighing 500 pounds. The barrel has a hidden catch, which can be found with a successful DC 20 INT (Investigation) check. Releasing the catch unlocks a hatch at one end of the barrel, allowing two Medium or smaller creatures to crawl inside."},{"id":"armor-of-resistance","name":"Armor of Resistance","type":"Armor (Light)","rarity":"rare","attunement":true,"text":"You are resistant to one type of damage while you wear this armor. The GM chooses the type or determines it randomly from the options below."},{"id":"arrow-of-slaying","name":"Arrow of Slaying","type":"Weapon (Arrow)","rarity":"very rare","attunement":false,"text":"An arrow of slaying is a piece of magic ammunition effective against a particular kind of creature."},{"id":"arrow-catching-shield","name":"Arrow-Catching Shield","type":"Armor (Shield)","rarity":"rare","attunement":false,"text":"8,000 gp (Requires Attunement) You gain a +2 bonus to AC against ranged attacks while you wield this shield. This bonus is in addition to the shield’s normal bonus to AC."},{"id":"bag-of-beans","name":"Bag of Beans","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"Inside this heavy cloth bag are 3d4 dry beans. The bag weighs 1/2 pound plus 1/4 pound for each bean it contains. If you dump the bag’s contents out on the ground, they explode in a 10-foot radius, extending from the beans."},{"id":"bag-of-holding","name":"Bag of Holding","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This bag has an interior space considerably larger than its outside dimensions, roughly 2 feet in diameter at the mouth and 4 feet deep. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 15 pounds, regardless of its contents."},{"id":"bag-of-tricks","name":"Bag of Tricks","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This ordinary bag, made from gray, rust, or tan cloth, appears empty. Reaching inside the bag, however, reveals a small, fuzzy object. The bag weighs 1/2 pound. You can use an action to pull the fuzzy object from the bag and throw it up to 20 feet."},{"id":"bagpipes-of-battle","name":"Bagpipes of Battle","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) You must have proficiency with instruments (woodwinds) to use these bagpipes. You can use an action to play them and create a fearsome and inspiring tune. Each ally within 60 feet of you that can hear the tune gains a d12 Bardic Inspiration die for 10 minutes."},{"id":"bead-of-force","name":"Bead of Force","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This small, black sphere measures 3/4 of an inch in diameter and weighs 1 ounce. Typically, 1d4 + 4 beads of force are found together. You can use an action to throw a bead up to 60 feet. The bead explodes on impact and is destroyed."},{"id":"beast-buckle","name":"Beast Buckle","type":"Wondrous Item","rarity":"common","attunement":false,"text":"(Requires Attunement) This burnished brass belt buckle is shaped like a heavily muscled bison. While attuned, your hit points and hit point maximum increase by 5. 165 5 EQUIPMENT & MAGIC ITEMS"},{"id":"belt-of-dwarvenkind","name":"Belt of Dwarvenkind","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While wearing this belt, you gain the following benefits: • Your CON score increases by 2, to a maximum of 20. • You have advantage on CHA (Persuasion) checks made to interact with dwarves."},{"id":"berserker-axe","name":"Berserker Axe","type":"Weapon (Any Axe)","rarity":"rare","attunement":false,"text":"(Requires Attunement) You gain a +1 bonus to attack and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your hit point maximum increases by 1 for each level you have attained. Curse. This axe is cursed, and becoming attuned to it extends the curse to you."},{"id":"boots-of-elvenkind","name":"Boots of Elvenkind","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have advantage on DEX (Stealth) checks that rely on moving silently."},{"id":"boots-of-galloping","name":"Boots of Galloping","type":"Wondrous Item","rarity":"common","attunement":false,"text":"These white and brown suede boots are patterned like a horse’s coat. While wearing the boots, you can use a bonus action to make your footfalls sound like those of a galloping horse until the start of your next turn. The sound is audible out to 300 feet."},{"id":"boots-of-levitation","name":"Boots of Levitation","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While you wear these boots, you can use an action to cast the levitate spell from them on yourself."},{"id":"boots-of-speed","name":"Boots of Speed","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While you wear these boots, you can use a bonus action and click the boots’ heels together. If you do, the boots double your walking speed, and any creature that makes an opportunity attack against you has disadvantage on the attack roll."},{"id":"boots-of-striding-and-springing","name":"Boots of Striding and Springing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While you wear these boots, your walking speed becomes 30 feet, unless your walking speed is higher, and your speed isn’t reduced if you are encumbered or wearing heavy armor."},{"id":"boots-of-the-winterlands","name":"Boots of the Winterlands","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) These furred boots are snug and feel quite warm. While you wear them, you gain the following benefits: • You are resistant to cold damage. • You ignore difficult terrain created by ice or snow."},{"id":"bowl-of-commanding-water-elementals","name":"Bowl of Commanding Water Elementals","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This bowl is about 1 foot in diameter and half as deep. It weighs 3 pounds and holds about 3 gallons. While this bowl is filled with water, you can use an action to speak the bowl’s command word and summon a water elemental , as if you had cast the conjure elemental spell."},{"id":"bracers-of-archery","name":"Bracers of Archery","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing these bracers, you have proficiency with longbow and shortbow, and you gain a +2 bonus to damage rolls on ranged attacks made with such weapons."},{"id":"bracers-of-baleful-reprisal","name":"Bracers of Baleful Reprisal","type":"Wondrous Item","rarity":"common","attunement":false,"text":"(Requires Attunement) These metal bracers are made of fire-blued steel. While attuned, when a creature you can see misses you with an attack, you can use your reaction to balefully mark the creature for 1 minute."},{"id":"bracers-of-defense","name":"Bracers of Defense","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While wearing these bracers, you gain a +2 bonus to AC if you are wearing no armor and using no shield."},{"id":"brazier-of-commanding-fire-elementals","name":"Brazier of Commanding Fire Elementals","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This brass brazier weighs 5 pounds. While a fire burns in it, you can use an action to speak the brazier’s command word and summon a fire elemental , as if you had cast the conjure elemental spell. The brazier can’t be used this way again until the next dawn."},{"id":"brooch-of-shielding","name":"Brooch of Shielding","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this brooch, you are resistant to force damage, and you are immune to the damage from the magic missile spell."},{"id":"broom-of-flying","name":"Broom of Flying","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This wooden broom weighs 3 pounds. It functions like a mundane broom until you stand astride it and speak its command word. It then hovers beneath you and can be ridden in the air. It has a flying speed of 50 feet."},{"id":"cape-of-the-mountebank","name":"Cape of the Mountebank","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This cape smells faintly of brimstone. While wearing it, you can use it to cast the dimension door spell as an action. This property of the cape can’t be used again until the next dawn. When you disappear, you leave behind a cloud of smoke, and you appear in a cloud of smoke at your destination."},{"id":"carpet-of-flying","name":"Carpet of Flying","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"You can speak the carpet’s command word as an action to make the carpet hover and fly. It moves according to your spoken directions, provided that you are within 30 feet of it. Four sizes of carpet of flying exist. The GM chooses the size of a given carpet or determines it randomly."},{"id":"censer-of-controlling-air-elementals","name":"Censer of Controlling Air Elementals","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This 6-inch-wide, 1-foot-high vessel resembles a chalice with a decorated lid. It weighs 1 pound. While incense is burning in this censer, you can use an action to speak the censer’s command word and summon an air elemental , as if you had cast the conjure elemental spell."},{"id":"chime-of-opening","name":"Chime of Opening","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This hollow metal tube measures about 1 foot long and weighs 1 pound. You can strike it as an action, pointing it at an object within 120 feet of you that can be opened, such as a door, lid, or lock."},{"id":"circlet-of-blasting","name":"Circlet of Blasting","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While wearing this circlet, you can use an action to cast the scorching ray spell with it. When you make the spell’s attacks, you do so with an attack bonus of +5. The circlet can’t be used this way again until the next dawn."},{"id":"cloak-of-arachnida","name":"Cloak of Arachnida","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This fine garment is made of black silk interwoven with faint silvery threads. While wearing it, you gain the following benefits: • You are resistant to poison damage. • You have a climbing speed equal to your walking speed."},{"id":"cloak-of-displacement","name":"Cloak of Displacement","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While you wear this cloak, it projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have disadvantage on attack rolls against you."},{"id":"cloak-of-elvenkind","name":"Cloak of Elvenkind","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While you wear this cloak with its hood up, WIS (Perception) checks made to see you have disadvantage, and you have advantage on DEX (Stealth) checks made to hide, as the cloak’s color shifts to camouflage you. Pulling the hood up or down requires an action."},{"id":"cloak-of-protection","name":"Cloak of Protection","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) You gain a +1 bonus to AC and saves while you wear this cloak."},{"id":"cloak-of-the-bat","name":"Cloak of the Bat","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While wearing this cloak, you have advantage on DEX (Stealth) checks. In an area of dim light or darkness, you can grip the edges of the cloak with both hands and use it to fly at a speed of 40 feet."},{"id":"cloak-of-the-manta-ray","name":"Cloak of the Manta Ray","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While wearing this cloak with its hood up, you can breathe underwater, and you have a swimming speed of 60 feet. Pulling the hood up or down requires an action."},{"id":"cube-of-force","name":"Cube of Force","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) This cube is about 1 inch across. Each face has a distinct marking that can be pressed. The cube starts with 36 charges. You can use an action to press one of the cube’s faces, expending a number of charges based on the chosen face, as shown in the Cube of Force Faces table."},{"id":"dagger-of-venom","name":"Dagger of Venom","type":"Weapon (Dagger)","rarity":"rare","attunement":false,"text":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. You can use an action to cause thick, black poison to coat the blade. The poison remains for 1 minute or until an attack using this weapon hits a creature."},{"id":"dancing-lockpicks","name":"Dancing Lockpicks","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This magic item functions as a normal set of thieves’ tools (see Tools in Chapter 5 ) in addition to its other magical properties. Dancing lockpicks have 3 charges."},{"id":"dancing-sword","name":"Dancing Sword","type":"Weapon (Any Sword)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) You can use a bonus action to toss this magic sword into the air and speak the command word. When you do so, the sword begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of it."},{"id":"decanter-of-endless-water","name":"Decanter of Endless Water","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This stoppered flask sloshes when shaken, as if it contains water. The decanter weighs 2 pounds. You can use an action to remove the stopper and speak one of three command words, whereupon an amount of fresh water or salt water (your choice) pours out of the flask."},{"id":"defender","name":"Defender","type":"Weapon (Any Sword)","rarity":"legendary","attunement":false,"text":"(Requires Attunement) You gain a +3 bonus to attack and damage rolls made with this magic weapon. The first time you attack with this sword on each of your turns, you can transfer some or all of the sword’s bonus to your AC, instead of using the bonus on attacks that turn."},{"id":"demon-armor","name":"Demon Armor","type":"Armor (Plate)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While wearing this armor, you gain a +1 bonus to AC, and you can understand and speak Abyssal."},{"id":"dimensional-shackles","name":"Dimensional Shackles","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"You can use an action to place these shackles on an incapacitated creature. The shackles adjust to fit a creature of Small to Large size."},{"id":"dragon-scale-mail","name":"Dragon Scale Mail","type":"Armor (Scale Mail)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) Dragon scale mail is made of the scales of one kind of dragon. Sometimes dragons collect their cast-off scales and gift them. Other times, hunters skin and preserve the hide of a dead dragon. In either case, dragon scale mail is highly valued."},{"id":"dragon-slayer","name":"Dragon Slayer","type":"Weapon (Any Sword)","rarity":"rare","attunement":false,"text":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. When you hit a dragon with this weapon, the target takes an extra 3d6 damage of the weapon’s type. For the purpose of this weapon, “dragon” refers to any creature with the Dragon type, including dragon turtles and wyverns."},{"id":"dust-of-disappearance","name":"Dust of Disappearance","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"Found in a small packet, this powder resembles very fine sand. There is enough of it for one use. When you use an action to throw the dust into the air, you and each creature and object within 10 feet of you become invisible for 2d4 minutes."},{"id":"dust-of-dryness","name":"Dust of Dryness","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This small packet contains 1d6 + 4 pinches of dust. You can use an action to sprinkle a pinch of it over water. The dust turns a cube of water 15 feet on a side into one marble- sized pellet, which floats or rests near where the dust was sprinkled. The pellet’s weight is negligible."},{"id":"dust-of-sneezing-and-choking","name":"Dust of Sneezing and Choking","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"Found in a small container, this powder resembles very fine sand. It appears to be dust of disappearance , and an identify spell reveals it to be such. There is enough of it for one use."},{"id":"dwarven-plate","name":"Dwarven Plate","type":"Armor (Plate)","rarity":"very rare","attunement":false,"text":"While wearing this armor, you gain a +2 bonus to AC. In addition, if an effect moves you against your will along the ground, you can use your reaction to reduce the distance you are moved by up to 10 feet. 172 PLAYER'S GUIDE"},{"id":"dwarven-thrower","name":"Dwarven Thrower","type":"Weapon (Warhammer)","rarity":"very rare","attunement":false,"text":"(Requires Attunement by a Dwarf) You gain a +3 bonus to attack and damage rolls made with this magic weapon. It has the Thrown property with a normal range of 20 feet and a long range of 60 feet."},{"id":"efficient-quiver","name":"Efficient Quiver","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"Each of this quiver’s three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds. The shortest compartment can hold up to sixty arrows, bolts, or similar objects."},{"id":"efreeti-bottle","name":"Efreeti Bottle","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"This painted brass bottle weighs 1 pound. When you use an action to remove the stopper, a cloud of thick smoke flows out of the bottle. At the end of your turn, the smoke disappears with a flash of harmless fire, and an efreeti appears in an unoccupied space within 30 feet of you."},{"id":"elemental-gem","name":"Elemental Gem","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This gem contains a mote of elemental energy. When you use an action to break the gem, an elemental is summoned as if you had cast the conjure elemental spell, and the gem’s magic is lost. The type of gem determines the elemental summoned by the spell."},{"id":"eyes-of-charming","name":"Eyes of Charming","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"These crystal lenses fit over the eyes. They have 3 charges and regain all expended charges daily at dawn. While wearing them, you can expend 1 charge as an action to cast the charm spell (save DC 13) on a Humanoid within 30 feet of you, provided that you and the target can see each other."},{"id":"eyes-of-minute-seeing","name":"Eyes of Minute Seeing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"These crystal lenses fit over the eyes. While wearing them, you can see much better than normal to a range of 1 foot. You have advantage on INT (Investigation) checks that rely on sight while searching an area or studying an object within that range."},{"id":"eyes-of-the-eagle","name":"Eyes of the Eagle","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) These crystal lenses fit over the eyes. While wearing them, you have advantage on WIS (Perception) checks that rely on sight. In conditions of clear visibility, you can make out details of even extremely distant creatures and objects as small as 2 feet across."},{"id":"feather-token","name":"Feather Token","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This Tiny object looks like a feather. Different types exist, each with a different single-use effect. The GM chooses the kind of feather token or determines it randomly."},{"id":"featherlight-armor","name":"Featherlight Armor","type":"Armor (Light)","rarity":"common","attunement":false,"text":"+ armor base cost These suits of armor are etched with cloud and feather motifs. When you would take falling damage while wearing this armor, roll a d12 and subtract the result from the damage taken."},{"id":"flame-tongue","name":"Flame Tongue","type":"Weapon (Any Sword)","rarity":"rare","attunement":false,"text":"(Requires Attunement) You can use a bonus action to speak this magic sword’s command word, causing flames to erupt from the blade. The flames are harmless to you and the weapon. These flames shed bright light in a 40-foot radius and dim light for an additional 40 feet."},{"id":"flute-of-saurian-summoning","name":"Flute of Saurian Summoning","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This scaly, clawed flute has a musky smell, and it releases a predatory, screeching roar with reptilian overtones when blown. You must have proficiency with instruments (woodwinds) to use this flute. You can use an action to play the flute and conjure dinosaurs."},{"id":"frost-brand","name":"Frost Brand","type":"Weapon (Any Sword)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) When you hit with an attack using this magic sword, the target takes an extra 1d6 cold damage. In addition, while you hold the sword, you are resistant to fire damage."},{"id":"gauntlets-of-ogre-power","name":"Gauntlets of Ogre Power","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) Your STR score is 19 while you wear these gauntlets. They have no effect on you if your STR is already 19 or higher."},{"id":"gem-of-brightness","name":"Gem of Brightness","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This prism has 50 charges. While you are holding it, you can use an action to speak one of three command words to cause one of the following effects: • The first command word causes the gem to shed bright light in a 30-foot radius and dim light for an additional 30 feet."},{"id":"gem-of-seeing","name":"Gem of Seeing","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) This gem has 3 charges. As an action, you can speak the gem’s command word and expend 1 charge. For the next 10 minutes, you have truesight to a range of 120 feet when you peer through the gem. The gem regains 1d3 expended charges daily at dawn."},{"id":"giant-slayer","name":"Giant Slayer","type":"Weapon (Any Axe or Sword)","rarity":"rare","attunement":false,"text":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. When you use it to hit a creature with the Giant type, the creature takes an extra 2d6 damage of the weapon’s type and must succeed on a DC 15 STR save or fall prone."},{"id":"gloves-of-missile-snaring","name":"Gloves of Missile Snaring","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) These gloves seem to almost meld into your hands when you don them. When a ranged weapon attack hits you while you’re wearing them, and you have a free hand, you can use your reaction to reduce the damage by 1d10 + your DEX modifier."},{"id":"gloves-of-swimming-and-climbing","name":"Gloves of Swimming and Climbing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing these gloves, climbing and swimming don’t cost you extra movement, and you gain a +5 bonus to STR (Athletics) checks made to climb or swim."},{"id":"goggles-of-night","name":"Goggles of Night","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While wearing these goggles, you have darkvision to a range of 60 feet. If you already have darkvision, wearing the goggles increases its range by 60 feet."},{"id":"hampering-ammunition","name":"Hampering Ammunition","type":"Weapon (Any Ammunition)","rarity":"common","attunement":false,"text":"+ ammunition base cost This ammunition slows a target’s movement. A creature hit by the ammunition must succeed on a DC 10 CON save or have their base movement speed reduced by 5 feet for 1 minute. An affected target can repeat this save at the end of each turn to end the reduction."},{"id":"handy-haversack","name":"Handy Haversack","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 20 pounds of material, not exceeding a volume of 2 cubic feet. The large central pouch can hold up to 8 cubic feet or 80 pounds of material."},{"id":"hat-of-disguise","name":"Hat of Disguise","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this hat, you can use an action to cast the disguise self spell from it. The spell ends if the hat is removed."},{"id":"headband-of-intellect","name":"Headband of Intellect","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) Your INT score is 19 while you wear this headband. It has no effect on you if your INT is already 19 or higher."},{"id":"helm-of-brilliance","name":"Helm of Brilliance","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This dazzling helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic."},{"id":"helm-of-comprehending-languages","name":"Helm of Comprehending Languages","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While wearing this helm, you can use an action to cast the comprehend languages spell from it."},{"id":"helm-of-telepathy","name":"Helm of Telepathy","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this helm, you can use an action to cast the detect thoughts spell (save DC 13) from it. As long as you maintain concentration on the spell, you can use a bonus action to send a telepathic message to a creature you are focused on."},{"id":"helm-of-teleportation","name":"Helm of Teleportation","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) This helm has 3 charges. While wearing it, you can use an action and expend 1 charge to cast the teleport spell from it. The helm regains 1d3 expended charges daily at dawn."},{"id":"holy-avenger","name":"Holy Avenger","type":"Weapon (Any Sword)","rarity":"legendary","attunement":false,"text":"(Requires Attunement) You gain a +3 bonus to attack and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, the target takes an extra 2d10 radiant damage. While you wield this sword, it creates an aura in a 10-foot radius around you."},{"id":"horn-of-blasting","name":"Horn of Blasting","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"You can use an action to speak the horn’s command word and then blow the horn, which emits a thunderous blast in a 30-foot cone that is audible to 600 feet. Each creature in the cone must make a DC 15 CON save. On a failed save, a creature takes 5d6 thunder damage and is deafened for 1 minute."},{"id":"horseshoes-of-a-zephyr","name":"Horseshoes of a Zephyr","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"These iron horseshoes come in a set of four. While all four shoes are affixed to the hooves of a horse or similar creature, they allow the creature to move normally while floating 4 inches above the ground."},{"id":"howling-arrow","name":"Howling Arrow","type":"Weapon (any ammunition)","rarity":"common","attunement":false,"text":"This ammunition is made from hollowed antler or bone and emits a shrill whistle while airborne. When you hit a creature with it, the ammunition deals only half its damage, but the target must succeed on a DC 11 CON save or be deafened until the end of its next turn."},{"id":"immovable-rod","name":"Immovable Rod","type":"Rod","rarity":"uncommon","attunement":false,"text":"This flat iron rod has a button on one end. You can use an action to press the button, which causes the rod to become magically fixed in place. Until you or another creature uses an action to push the button again, the rod doesn’t move, even if it defies gravity."},{"id":"instant-fortress","name":"Instant Fortress","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"You can use an action to place this 1-inch metal cube on the ground and speak its command word. The cube rapidly grows into a fortress that remains until you use an action to dismiss it, which works only if the fortress is empty."},{"id":"iron-bands-of-binding","name":"Iron Bands of Binding","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound. You can use an action to speak the command word and throw the sphere at a Huge or smaller creature you can see within 60 feet of you. As the sphere moves through the air, it opens into a tangle of metal bands."},{"id":"iron-flask","name":"Iron Flask","type":"Wondrous Item","rarity":"legendary","attunement":false,"text":"This iron bottle has a brass stopper. You can use an action to speak the flask’s command word, targeting a creature that you can see within 60 feet of you."},{"id":"javelin-of-lightning","name":"Javelin of Lightning","type":"Weapon (Javelin)","rarity":"uncommon","attunement":false,"text":"This javelin is a magic weapon. When you hurl it and speak its command word, it transforms into a bolt of lightning, forming a line 5 feet wide that extends from you to a target within 120 feet."},{"id":"lantern-of-revealing","name":"Lantern of Revealing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding bright light in a 30-foot radius and dim light for an additional 30 feet. Invisible creatures and objects are visible if they are in the lantern’s bright light."},{"id":"luck-blade","name":"Luck Blade","type":"Weapon (Any Sword)","rarity":"legendary","attunement":false,"text":"(Requires Attunement) You gain a +1 bonus to attack and damage rolls made with this magic weapon. While carried, you also gain a +1 bonus to saves. Luck. While you carry this sword, you can call on its luck (no action required) to reroll one attack roll, ability check, or save you dislike."},{"id":"lucky-roller-dice","name":"Lucky Roller Dice","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This pair of bone-carved dice has 5 charges. Once per day, you can use an action to expend 1 charge and immediately gain 1 Luck. Once all charges are spent, the dice become nonmagical."},{"id":"mace-of-disruption","name":"Mace of Disruption","type":"Weapon (Mace)","rarity":"rare","attunement":false,"text":"(Requires Attunement) When you hit a Fiend or Undead with this magic weapon, the target takes an extra 2d6 radiant damage. If the target has 25 HP or fewer after taking this damage, it must succeed on a DC 15 WIS save or be destroyed."},{"id":"mace-of-smiting","name":"Mace of Smiting","type":"Weapon (Mace)","rarity":"rare","attunement":false,"text":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. The bonus increases to +3 when you use the mace to attack a Construct. When you roll a 20 on an attack roll with this weapon, the target takes an extra 2d6 bludgeoning damage, or 4d6 bludgeoning damage if it’s a Construct."},{"id":"mace-of-terror","name":"Mace of Terror","type":"Weapon (Mace)","rarity":"rare","attunement":false,"text":"(Requires Attunement) This magic weapon has 3 charges. While holding it, you can use an action and expend 1 charge to release a wave of terror. Each creature of your choice in a 30-foot radius extending from you must succeed on a DC 15 WIS save or become frightened of you for 1 minute."},{"id":"mailbreaker","name":"Mailbreaker","type":"Weapon (Warhammer)","rarity":"common","attunement":false,"text":"This hammer’s face is covered with armor-shredding teeth. When you make a successful melee weapon attack against a creature wearing armor, you can reduce your target’s AC by 1 in addition to dealing normal damage. A set of armor can’t be affected by this feature again until it is repaired."},{"id":"mantle-of-spell-resistance","name":"Mantle of Spell Resistance","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) You have advantage on saves against spells while you wear this cloak."},{"id":"manual-of-golems","name":"Manual of Golems","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"This tome contains information and incantations necessary to make a particular type of creature with the Golem tag. The GM chooses the type or determines it randomly. To decipher and use the manual, you must be a spellcaster with at least two 5th-circle spell slots."},{"id":"manuals-of-advantageous-exertion","name":"Manuals of Advantageous Exertion","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"These handwritten books contain exercises and insights into improving your ability scores. Their words are charged with magic."},{"id":"marvelous-pigments","name":"Marvelous Pigments","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"Typically found in 1d4 pots inside a fine wooden box with a brush (weighing 1 pound in total), these pigments allow you to create three-dimensional objects by painting them in two dimensions. The paint flows from the brush to form the desired object as you concentrate on its image."},{"id":"medallion-of-thoughts","name":"Medallion of Thoughts","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) This medallion has 3 charges. While wearing it, you can use an action and expend 1 charge to cast the detect thoughts spell (save DC 13) from it. The medallion regains 1d3 expended charges daily at dawn."},{"id":"necklace-of-adaptation","name":"Necklace of Adaptation","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this necklace, you can breathe normally in any environment. You also have advantage on saves made against harmful gases and vapors, such as cloudkill and stinking cloud effects, inhaled poisons, and the breath weapons of some dragons."},{"id":"necklace-of-fireballs","name":"Necklace of Fireballs","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This necklace has 1d6 + 3 beads hanging from it. You can use an action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a 3rd-circle fireball spell (save DC 15). You can hurl multiple beads, or even the whole necklace, as one action."},{"id":"necklace-of-prayer-beads","name":"Necklace of Prayer Beads","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Cleric, Druid, or Paladin) This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz. It also has nonmagical beads made from stones such as amber, bloodstone, citrine, coral, jade, pearl, or quartz."},{"id":"nine-lives-stealer","name":"Nine Lives Stealer","type":"Weapon (Any Sword)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) You gain a +2 bonus to attack and damage rolls made with this magic weapon. The sword has 1d8 + 1 charges."},{"id":"oathbow","name":"Oathbow","type":"Weapon (Longbow)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) When you nock an arrow on this bow, it whispers in Elvish, “Swift defeat to my enemies.” When you use this weapon to make a ranged attack, you can, as a command phrase, say, “Swift death to you who have wronged me."},{"id":"oil-of-etherealness","name":"Oil of Etherealness","type":"Potion","rarity":"rare","attunement":false,"text":"Beads of this cloudy gray oil form on the outside of its container and quickly evaporate. The oil can cover a Medium or smaller creature, along with the equipment it’s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes."},{"id":"oil-of-sharpness","name":"Oil of Sharpness","type":"Potion","rarity":"very rare","attunement":false,"text":"This clear, gelatinous oil sparkles with tiny, ultrathin silver shards. The oil can coat one slashing or piercing weapon or up to 5 pieces of slashing or piercing ammunition. Applying the oil takes 1 minute. For 1 hour, the coated item is magical and has a +3 bonus to attack and damage rolls."},{"id":"oil-of-slipperiness","name":"Oil of Slipperiness","type":"Potion","rarity":"uncommon","attunement":false,"text":"This sticky black unguent is thick and heavy in the container, but it flows quickly when poured. The oil can cover a Medium or smaller creature, along with the equipment it wears and carries (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes."},{"id":"pearl-of-power","name":"Pearl of Power","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement by a Spellcaster) While this pearl is on your person, you can use an action to speak its command word and regain one expended spell slot. If the expended slot was of 4th circle or higher, the new slot is 3rd circle."},{"id":"pendulous-periapt","name":"Pendulous Periapt","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This clockwork necklace contains tiny weights and gyroscopes enchanted to maintain balance with each other. When you make a weapon attack while wearing the necklace, you can forgo rolling a d20 to choose a result of 1 (failing in this way doesn't generate Luck)."},{"id":"periapt-of-health","name":"Periapt of Health","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"You are immune to contracting any disease while you wear this pendant. If you are already infected with a disease, the effects are suppressed while you wear the pendant."},{"id":"periapt-of-proof-against-poison","name":"Periapt of Proof against Poison","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This delicate silver chain has a brilliant-cut black and green gem pendant. While you wear it, poisons have no effect on you. You are immune to the poisoned condition and to poison damage."},{"id":"periapt-of-wound-closure","name":"Periapt of Wound Closure","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While you wear this pendant, you stabilize whenever you are dying at the start of your turn. In addition, when you roll a hit die to regain hit points, double the number of hit points it restores."},{"id":"periapt-of-the-small-and-mighty","name":"Periapt of the Small and Mighty","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This brass locket contains an image of a smiling kobold. While wearing the amulet, you can use the Help action as a bonus action. Once used, you can’t use this property again until you spend 1 Luck to recharge the amulet (no action required to recharge)."},{"id":"pipes-of-haunting","name":"Pipes of Haunting","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"You must have proficiency with instruments (woodwinds) to use these pipes. They have 3 charges. You can use an action to play them and expend 1 charge to create an eerie, spellbinding tune."},{"id":"portable-hole","name":"Portable Hole","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter."},{"id":"potion-of-animal-friendship","name":"Potion of Animal Friendship","type":"Potion","rarity":"uncommon","attunement":false,"text":"When you drink this potion, animals tend to be friendly to you for 1 hour. For the duration, you can use an action to cast the animal friendship spell (save DC 13) at any time."},{"id":"potion-of-clairvoyance","name":"Potion of Clairvoyance","type":"Potion","rarity":"rare","attunement":false,"text":"When you drink this potion, you gain the effect of the clairvoyance spell. An eyeball bobs in this yellowish liquid but vanishes when the potion is opened."},{"id":"potion-of-climbing","name":"Potion of Climbing","type":"Potion","rarity":"uncommon","attunement":false,"text":"When you drink this potion, you gain a climbing speed equal to your walking speed for 1 hour. During this time, you have advantage on STR (Athletics) checks you make to climb. The potion is separated into brown, silver, and gray layers resembling bands of stone."},{"id":"potion-of-diminution","name":"Potion of Diminution","type":"Potion","rarity":"rare","attunement":false,"text":"When you drink this potion, you gain the “reduce” effect of the enlarge/reduce spell for 1d4 hours (no concentration required). The red in the potion’s liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it. 184 PLAYER'S GUIDE"},{"id":"potion-of-due-notice","name":"Potion of Due Notice","type":"Potion","rarity":"common","attunement":false,"text":"When you drink this potion, double your PB for the purpose of calculating your passive Insight, Investigation, and Perception scores for 1 hour. If you don't have proficiency in any of these skills, you gain proficiency in them for the duration of the potion."},{"id":"potion-of-flying","name":"Potion of Flying","type":"Potion","rarity":"very rare","attunement":false,"text":"When you drink this potion, you gain a flying speed equal to your walking speed for 1 hour and can hover. If you’re in the air when the potion wears off, you fall unless you have some other means of staying aloft."},{"id":"potion-of-gaseous-form","name":"Potion of Gaseous Form","type":"Potion","rarity":"rare","attunement":false,"text":"When you drink this potion, you gain the effect of the gaseous form spell for 1 hour (no concentration required) or until you end the effect as a bonus action. This potion’s container seems to hold fog that moves and pours like water."},{"id":"potion-of-growth","name":"Potion of Growth","type":"Potion","rarity":"uncommon","attunement":false,"text":"When you drink this potion, you gain the “enlarge” effect of the enlarge/reduce spell for 1d4 hours (no concentration required). The red in the potion’s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts."},{"id":"potion-of-heroism","name":"Potion of Heroism","type":"Potion","rarity":"rare","attunement":false,"text":"For 1 hour after drinking it, you gain 10 temporary HP that last for 1 hour. For the same duration, you are under the effect of the bless spell (no concentration required). This blue potion bubbles and steams as if boiling."},{"id":"potion-of-invisibility","name":"Potion of Invisibility","type":"Potion","rarity":"very rare","attunement":false,"text":"When you drink this potion, you become invisible for 1 hour. Anything you wear or carry is invisible with you. The effect ends early if you attack or cast a spell. This potion’s container looks empty but feels as though it holds liquid."},{"id":"potion-of-mind-reading","name":"Potion of Mind Reading","type":"Potion","rarity":"rare","attunement":false,"text":"When you drink this potion, you gain the effect of the detect thoughts spell (save DC 13). The potion’s dense, purple liquid has an ovoid cloud of pink floating in it."},{"id":"potion-of-resistance","name":"Potion of Resistance","type":"Potion","rarity":"uncommon","attunement":false,"text":"When you drink this potion, you become resistant to one type of damage for 1 hour. The GM chooses the type or determines it randomly from the options below."},{"id":"potion-of-speed","name":"Potion of Speed","type":"Potion","rarity":"very rare","attunement":false,"text":"When you drink this potion, you gain the effect of the haste spell for 1 minute (no concentration required). The potion’s yellow fluid is streaked with black and swirls on its own ."},{"id":"potion-of-water-breathing","name":"Potion of Water Breathing","type":"Potion","rarity":"uncommon","attunement":false,"text":"You can breathe underwater for 1 hour after drinking this potion. Its cloudy green fluid smells of the sea and has a jellyfish-like bubble floating in it. 185 5 EQUIPMENT & MAGIC ITEMS"},{"id":"quick-quaff-bandolier","name":"Quick Quaff Bandolier","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This practical three-slot bandolier has a sewn-in bottle opener, an always-warm wax melter, and a wine key on a chain. Over the course of 1 minute, which can be done as part of a short or long rest, you can load up to three potions into the bandolier’s slots."},{"id":"quickbuckle-armor","name":"Quickbuckle Armor","type":"Armor (Any)","rarity":"common","attunement":false,"text":"While carrying or wearing this armor, you can use your action to speak a command word to instantly don or doff it."},{"id":"quillback-armor","name":"Quillback Armor","type":"Armor (Leather or Hide)","rarity":"common","attunement":false,"text":"This armor has sharp porcupine quills sewn throughout the body. While you are grappling a creature, the creature takes 1d4 damage at the start of each of your turns."},{"id":"reciprocating-polearm","name":"Reciprocating Polearm","type":"Weapon (Spear)","rarity":"common","attunement":false,"text":"+ weapon base cost When you miss an attack with this clockwork-enhanced polearm, you can gain advantage on your next attack made with it within 1 minute. Once used, this property can’t be used again for 1 minute."},{"id":"restorative-ointment","name":"Restorative Ointment","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This glass jar, 3 inches in diameter, contains 1d4 + 1 doses of a thick mixture that smells faintly of aloe. The jar and its contents weigh 1/2 pound. As an action, one dose of the ointment can be swallowed or applied to the skin."},{"id":"returning-charm","name":"Returning Charm","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This golden tassel has a series of loops that wrap around each other and connect in a returning pattern at their beginning. You must spend 1 minute to tie the tassel onto a weapon with the Thrown property to use the charm’s effect."},{"id":"ring-of-animal-influence","name":"Ring of Animal Influence","type":"Ring","rarity":"rare","attunement":false,"text":"This ring has 3 charges and regains 1d3 expended charges daily at dawn."},{"id":"ring-of-djinni-summoning","name":"Ring of Djinni Summoning","type":"Ring","rarity":"legendary","attunement":true,"text":"While wearing this ring, you can speak its command word as an action to summon a particular djinni from the Elemental Plane of Air. The djinni appears in an unoccupied space you choose within 120 feet of you."},{"id":"ring-of-evasion","name":"Ring of Evasion","type":"Ring","rarity":"rare","attunement":true,"text":"This ring has 3 charges and regains 1d3 expended charges daily at dawn. When you fail a DEX save while wearing it, you can use your reaction to expend 1 charge to succeed on that save instead."},{"id":"ring-of-feather-falling","name":"Ring of Feather Falling","type":"Ring","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling."},{"id":"ring-of-free-action","name":"Ring of Free Action","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) While you wear this ring, difficult terrain doesn’t cost you extra movement. In addition, magic can neither reduce your speed nor cause you to be paralyzed or restrained."},{"id":"ring-of-invisibility","name":"Ring of Invisibility","type":"Ring","rarity":"legendary","attunement":false,"text":"(Requires Attunement) While wearing this ring, you can turn invisible as an action. Anything you are wearing or carrying is invisible with you. You remain invisible until the ring is removed, until you attack or cast a spell, or until you use a bonus action to become visible again."},{"id":"ring-of-jumping","name":"Ring of Jumping","type":"Ring","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this ring, you can cast the jump spell from it as a bonus action. You can target only yourself with it."},{"id":"ring-of-mind-shielding","name":"Ring of Mind Shielding","type":"Ring","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, or know your creature type. Creatures can telepathically communicate with you only if you allow it."},{"id":"ring-of-protection","name":"Ring of Protection","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) You gain a +1 bonus to AC and saves while wearing this ring."},{"id":"ring-of-regeneration","name":"Ring of Regeneration","type":"Ring","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While wearing this ring, you regain 1d6 HP every 10 minutes, provided that you have at least 1 HP. If you lose a body part, the ring causes the missing part to regrow and return to full functionality after 1d6 + 1 days if you have at least 1 HP the whole time."},{"id":"ring-of-resistance","name":"Ring of Resistance","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) You are resistant to one damage type while wearing this ring. The gem in the ring indicates the type, which the GM chooses or determines randomly."},{"id":"ring-of-shooting-stars","name":"Ring of Shooting Stars","type":"Ring","rarity":"very rare","attunement":false,"text":"(Requires Attunement Outdoors at Night) While wearing this ring in dim light or darkness, as an action you can cast dancing lights and light from it. For its other properties, the ring has 6 charges. Faerie Fire. You can expend 1 charge as an action to cast faerie fire from the ring. Ball Lightning."},{"id":"ring-of-spell-storing","name":"Ring of Spell Storing","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) This ring stores spells cast into it, holding them until the attuned wearer uses them. The ring can store up to 5 circles’ worth of spells at a time. When found, it contains 1d6 − 1 circles of stored spells chosen by the GM."},{"id":"ring-of-spell-turning","name":"Ring of Spell Turning","type":"Ring","rarity":"legendary","attunement":false,"text":"(Requires Attunement) While wearing this ring, you have advantage on saves against any spell that targets only you."},{"id":"ring-of-swimming","name":"Ring of Swimming","type":"Ring","rarity":"uncommon","attunement":false,"text":"While wearing this ring, your swimming speed is 40 feet."},{"id":"ring-of-telekinesis","name":"Ring of Telekinesis","type":"Ring","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While wearing this ring, you can cast the telekinesis spell, but you can target only objects that aren’t being worn or carried. 188 PLAYER'S GUIDE"},{"id":"ring-of-three-wishes","name":"Ring of Three Wishes","type":"Ring","rarity":"legendary","attunement":false,"text":"This ring has 3 charges. While wearing it, you can use an action to expend 1 charge to cast the wish spell from it. The ring becomes nonmagical when you use the last charge."},{"id":"ring-of-warmth","name":"Ring of Warmth","type":"Ring","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While wearing this ring, you have resistance to cold damage. In addition, you and your equipment are unharmed by temperatures as low as -50 degrees Fahrenheit."},{"id":"ring-of-water-walking","name":"Ring of Water Walking","type":"Ring","rarity":"uncommon","attunement":false,"text":"While wearing this ring, you can stand on and move across any liquid surface as if it were solid ground."},{"id":"ring-of-x-ray-vision","name":"Ring of X-Ray Vision","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) While wearing this ring, you can use an action to speak its command word. When you do so, you can see into and through solid matter for 1 minute. This vision has a radius of 30 feet."},{"id":"ring-of-the-ram","name":"Ring of the Ram","type":"Ring","rarity":"rare","attunement":false,"text":"(Requires Attunement) This ring has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the ring, you can use an action to expend 1 to 3 of its charges to make a ranged spell attack against one creature or object that isn’t being carried within 60 feet of you."},{"id":"robe-of-eyes","name":"Robe of Eyes","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) This robe is adorned with eyelike patterns. While you wear the robe, you gain the following benefits: • You can see in all directions, and you have advantage on WIS (Perception) checks that rely on sight. • You have darkvision to a range of 120 feet."},{"id":"robe-of-scintillating-colors","name":"Robe of Scintillating Colors","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This robe has 3 charges and regains 1d3 expended charges daily at dawn. While you wear it, you can use an action and expend 1 charge to cause the garment to display a shifting pattern of dazzling hues until the end of your next turn."},{"id":"robe-of-stars","name":"Robe of Stars","type":"Wondrous Item","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This black or dark blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saves while you wear it. Six stars, located on the robe’s upper front portion, are particularly large."},{"id":"robe-of-useful-items","name":"Robe of Useful Items","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This robe has cloth patches of various shapes and colors covering it. While wearing the robe, you can use an action to detach one of the patches, causing it to become the object or creature it represents. Once the last patch is removed, the robe becomes an ordinary garment."},{"id":"robe-of-the-archmagi","name":"Robe of the Archmagi","type":"Wondrous Item","rarity":"legendary","attunement":false,"text":"(Requires Attunement by a Sorcerer, Warlock, or Wizard) This elegant garment is made from exquisite cloth of white, gray, or black and adorned with silvery runes. You gain these benefits while wearing the robe: • If you aren’t wearing armor, your base AC is 15 + your DEX modifier."},{"id":"rod-of-absorption","name":"Rod of Absorption","type":"Rod","rarity":"very rare","attunement":false,"text":"(Requires Attunement) While holding this rod, you can use your reaction to absorb a spell that targets only you. The absorbed spell’s effect is canceled, and the spell’s energy—not the spell itself—is stored in the rod. The energy has the same circle as the spell when it was cast."},{"id":"rod-of-alertness","name":"Rod of Alertness","type":"Rod","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This rod has a flanged head and the following properties. Alertness. While holding the rod, you have advantage on WIS (Perception) checks and on rolls for initiative. Spells."},{"id":"rod-of-rulership","name":"Rod of Rulership","type":"Rod","rarity":"rare","attunement":false,"text":"(Requires Attunement) You can use an action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of you. Each target must succeed on a DC 15 WIS save or be charmed by you for 8 hours."},{"id":"rod-of-security","name":"Rod of Security","type":"Rod","rarity":"very rare","attunement":false,"text":"While holding this rod, you can use an action to activate it. The rod then instantly transports you and up to 199 other willing creatures you can see to a paradise that exists in an extraplanar space. You choose the form that the paradise takes."},{"id":"rope-of-climbing","name":"Rope of Climbing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"This 60-foot length of silk rope weighs 3 pounds and can hold up to 3,000 pounds. If you hold one end of the rope and use an action to speak the command word, the rope animates. As a bonus action, you can command the other end to move toward a destination you choose."},{"id":"rope-of-entanglement","name":"Rope of Entanglement","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This rope is 30 feet long and weighs 3 pounds. If you hold one end of the rope and use an action to speak its command word, the other end darts forward to entangle a creature you can see within 20 feet of you. The target must succeed on a DC 15 DEX save or become restrained."},{"id":"scimitar-of-speed","name":"Scimitar of Speed","type":"Weapon (Scimitar)","rarity":"very rare","attunement":false,"text":"(Requires Attunement) You gain a +2 bonus to attack and damage rolls made with this magic weapon. In addition, you can make one attack with it as a bonus action on each of your turns."},{"id":"shield-of-clamor","name":"Shield of Clamor","type":"Armor (Shield)","rarity":"common","attunement":false,"text":"The surface of this shield vibrates unpredictably when struck. When a weapon attack misses you while you are wielding this shield, it makes one of several sounds that are audible to 60 feet."},{"id":"shield-of-missile-attraction","name":"Shield of Missile Attraction","type":"Armor (Shield)","rarity":"rare","attunement":false,"text":"(Requires Attunement) While holding this shield, you have resistance to damage from ranged weapon attacks. Curse. This shield is cursed. Attuning to it curses you until you are targeted by the remove curse spell or similar magic. Removing the shield fails to end the curse on you."},{"id":"slipforged-armor","name":"Slipforged Armor","type":"Armor (Any)","rarity":"common","attunement":false,"text":"Every surface of this armor is slippery and hard to hold on to. While you wear this armor, creatures have disadvantage on checks made to grapple or restrain you and you have advantage on checks made to escape a grapple."},{"id":"slippers-of-spider-climbing","name":"Slippers of Spider Climbing","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While you wear these light shoes, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free. You have a climbing speed equal to your walking speed."},{"id":"sovereign-glue","name":"Sovereign Glue","type":"Wondrous Item","rarity":"legendary","attunement":false,"text":"This viscous, milky-white substance can form a permanent bond between any two objects. It must be stored in a jar or flask that has been coated inside with oil of slipperiness . When found, a container contains 1d6 + 1 ounces. One ounce of the glue can cover a 1-foot square surface."},{"id":"spellguard-shield","name":"Spellguard Shield","type":"Armor (Shield)","rarity":"very rare","attunement":true,"text":"While wielding this shield, you have advantage on saves against spells and other magical effects, and spell attacks have disadvantage against you."},{"id":"staff-of-false-hues","name":"Staff of False Hues","type":"Staff","rarity":"common","attunement":false,"text":"If you touch a Large or smaller item with this staff, you can cause the item to temporarily become a different color of your choice. You can affect up to three different targets at a time like this. The color change lasts for 1 hour or until you choose to end the effect (no action required)."},{"id":"staff-of-fire","name":"Staff of Fire","type":"Staff","rarity":"very rare","attunement":false,"text":"(Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard) You have resistance to fire damage while you hold this staff. The staff has 10 charges."},{"id":"staff-of-frost","name":"Staff of Frost","type":"Staff","rarity":"very rare","attunement":false,"text":"(Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard) You have resistance to cold damage while you hold this staff. The staff has 10 charges."},{"id":"staff-of-healing","name":"Staff of Healing","type":"Staff","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Bard, Cleric, or Druid) This staff has 10 charges."},{"id":"staff-of-power","name":"Staff of Power","type":"Staff","rarity":"very rare","attunement":false,"text":"(Requires Attunement by a Sorcerer, Warlock, or Wizard) This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While holding it, you gain a +2 bonus to AC, saves, and spell attack rolls."},{"id":"staff-of-striking","name":"Staff of Striking","type":"Staff","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This staff can be wielded as a magic quarterstaff that grants a +3 bonus to attack and damage rolls made with it. The staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 of its charges as part of your Attack action."},{"id":"staff-of-swarming-insects","name":"Staff of Swarming Insects","type":"Staff","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard) This staff has 10 charges and regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll a d20. On a 1, a swarm of insects consumes and destroys the staff, then disperses."},{"id":"staff-of-thunder-and-lightning","name":"Staff of Thunder and Lightning","type":"Staff","rarity":"very rare","attunement":false,"text":"(Requires Attunement) This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. The staff has the following additional properties: Lightning."},{"id":"staff-of-withering","name":"Staff of Withering","type":"Staff","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Cleric, Druid, or Warlock) This staff has 3 charges and regains 1d3 expended charges daily at dawn. The staff can be wielded as a magic quarterstaff."},{"id":"staff-of-the-magi","name":"Staff of the Magi","type":"Staff","rarity":"legendary","attunement":false,"text":"(Requires Attunement by a Sorcerer, Warlock, or Wizard) This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls."},{"id":"staff-of-the-python","name":"Staff of the Python","type":"Staff","rarity":"uncommon","attunement":false,"text":"(Requires Attunement by a Cleric, Druid, or Wizard) You can use an action to speak this staff’s command word and throw the staff on the ground within 10 feet of you. The staff becomes a giant constrictor snake under your control and acts on its own initiative count."},{"id":"staff-of-the-woodlands","name":"Staff of the Woodlands","type":"Staff","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Druid) This staff can be wielded as a magic quarterstaff that grants a +2 bonus to attack and damage rolls made with it. While carrying it, you have a +2 bonus to spell attack rolls. The staff has 10 charges. The staff has the following additional properties: Spells."},{"id":"stone-of-controlling-earth-elementals","name":"Stone of Controlling Earth Elementals","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"This carved stone weighs 5 pounds. If the stone is touching the ground, you can use an action to speak its command word and summon an earth elemental , as if you had cast the conjure elemental spell. The stone can’t be used this way again until the next dawn."},{"id":"stone-of-good-luck-luckstone","name":"Stone of Good Luck (Luckstone)","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While carrying this polished agate, you gain a +1 bonus to ability checks and saves."},{"id":"sun-blade","name":"Sun Blade","type":"Weapon (Longsword)","rarity":"rare","attunement":false,"text":"(Requires Attunement) This item appears to be a longsword hilt. While grasping the hilt, you can use a bonus action to cause a blade of pure radiance to spring into existence, or make the blade disappear. While the blade exists, this magic longsword has the Finesse property."},{"id":"surefire-stock-pot","name":"Surefire Stock Pot","type":"Wondrous Item","rarity":"common","attunement":false,"text":"This large, steel stock pot has arcane symbols etched into its bottom. No matter how wet, windy, cold, or high in elevation you are, you can use this pot to cook food with no campfire, stove, or other heat source required."},{"id":"sword-of-life-stealing","name":"Sword of Life Stealing","type":"Weapon (Any Sword)","rarity":"rare","attunement":false,"text":"(Requires Attunement) When you attack a creature with this magic weapon and roll a 20 on the attack roll, that target takes an extra 3d6 necrotic damage, provided that the target isn’t a Construct or an Undead. You gain temporary HP equal to the extra damage dealt. 195 5 EQUIPMENT & MAGIC ITEMS"},{"id":"sword-of-sharpness","name":"Sword of Sharpness","type":"Weapon (Any Sword That Deals Slashing Damage)           60","rarity":"very rare","attunement":true,"text":"When you attack an object with this magic sword and hit, maximize your weapon damage dice against the target. When you attack a creature with this weapon and roll a 20 on the attack roll, that target takes an extra 4d6 slashing damage. Then roll another d20."},{"id":"sword-of-wounding","name":"Sword of Wounding","type":"Weapon (Any Sword)","rarity":"rare","attunement":false,"text":"(Requires Attunement) Hit points lost to this weapon’s damage can be regained only through a short or long rest, rather than by regeneration, magic, or any other means."},{"id":"trident-of-fish-command","name":"Trident of Fish Command","type":"Weapon (Trident)","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) This trident is a magic weapon. It has 3 charges and regains 1d3 expended charges daily at dawn. While you carry it, you can use an action and expend 1 charge to cast dominate (save DC 15) from it on a Beast that has an innate swimming speed."},{"id":"universal-solvent","name":"Universal Solvent","type":"Wondrous Item","rarity":"legendary","attunement":false,"text":"This tube holds milky liquid with a strong alcohol smell. You can use an action to pour its contents onto a surface within reach. The liquid instantly dissolves up to 1 square foot of adhesive it touches, including sovereign glue . 196 PLAYER'S GUIDE"},{"id":"vicious-weapon","name":"Vicious Weapon","type":"Weapon (Any)","rarity":"very rare","attunement":false,"text":"When you roll a 20 on your attack roll with this magic weapon, your critical hit deals an extra 2d6 damage of the weapon’s type to the target."},{"id":"vorpal-sword","name":"Vorpal Sword","type":"Weapon (Any Sword That Deals Slashing Damage)            50","rarity":"legendary","attunement":true,"text":"You gain a +3 bonus to attack and damage rolls made with this magic weapon. In addition, the weapon ignores resistance to slashing damage. When you attack a creature that has at least one head with this weapon and roll a 20 on the attack roll, you cut off one of the creature’s heads."},{"id":"wand-of-binding","name":"Wand of Binding","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll a d20. On a 1, it crumbles into ashes and is destroyed. The wand has the following additional properties: Spells."},{"id":"wand-of-enemy-detection","name":"Wand of Enemy Detection","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement) This wand has 7 charges. While holding it, you can use an action and expend 1 charge to speak its command word. For the next minute, you know the direction of the nearest creature hostile to you within 60 feet, but not its distance from you."},{"id":"wand-of-fireballs","name":"Wand of Fireballs","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the fireball spell (save DC 15) from it. For 1 charge, you cast the 3rd‑circle version of the spell."},{"id":"wand-of-lightning-bolts","name":"Wand of Lightning Bolts","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the lightning bolt spell (save DC 15) from it. For 1 charge, you cast the 3rd-circle version of the spell."},{"id":"wand-of-magic-detection","name":"Wand of Magic Detection","type":"Wand","rarity":"uncommon","attunement":false,"text":"This wand has 3 charges. While holding it, you can expend 1 charge as an action to cast the detect magic spell from it. The wand regains 1d3 expended charges daily at dawn."},{"id":"wand-of-magic-missiles","name":"Wand of Magic Missiles","type":"Wand","rarity":"uncommon","attunement":false,"text":"This wand has 7 charges. While holding it, you can use an action to expend 1 or more of its charges to cast the magic missile spell from it. For 1 charge, you cast the 1st-circle version of the spell. You can increase the spell slot circle by one for each additional charge you expend."},{"id":"wand-of-paralysis","name":"Wand of Paralysis","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cause a thin blue ray to streak from the tip toward a creature you can see within 60 feet of you."},{"id":"wand-of-polymorph","name":"Wand of Polymorph","type":"Wand","rarity":"very rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cast the polymorph spell (save DC 15) from it. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll a d20."},{"id":"wand-of-secrets","name":"Wand of Secrets","type":"Wand","rarity":"uncommon","attunement":false,"text":"This wand has 3 charges. While holding it, you can use an action to expend 1 of its charges, and if a secret door or trap is within 30 feet of you, the wand pulses and points at the one nearest to you. The wand regains 1d3 expended charges daily at dawn."},{"id":"wand-of-web","name":"Wand of Web","type":"Wand","rarity":"uncommon","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges to cast the web spell (save DC 15) from it. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll a d20."},{"id":"wand-of-wonder","name":"Wand of Wonder","type":"Wand","rarity":"rare","attunement":false,"text":"(Requires Attunement by a Spellcaster) This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges and choose a target within 120 feet of you. The target can be a creature, an object, or a point in space."},{"id":"wind-fan","name":"Wind Fan","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"While holding this fan, you can use an action to cast the gust of wind spell (save DC 13) from it. Once used, the fan shouldn’t be used again until the next dawn."},{"id":"winged-boots","name":"Winged Boots","type":"Wondrous Item","rarity":"uncommon","attunement":false,"text":"(Requires Attunement) While you wear these boots, you have a flying speed equal to your walking speed. You can use the boots to fly for up to 4 hours, all at once or in several shorter flights, each one using a minimum of 1 minute from the duration."},{"id":"wings-of-flying","name":"Wings of Flying","type":"Wondrous Item","rarity":"rare","attunement":false,"text":"(Requires Attunement) While wearing this cloak, you can use an action to speak its command word. This turns the cloak into a pair of bat wings or bird wings on your back for 1 hour or until you repeat the command word as an action. The wings give you a flying speed of 60 feet."}]

const BY_ID: Record<string, MagicItem> = Object.fromEntries(MAGIC_ITEMS.map((i) => [i.id, i]))

export const RARITY_ORDER: Rarity[] = ['common', 'uncommon', 'rare', 'very rare', 'legendary']

export function getMagicItem(id: string): MagicItem | undefined {
  return BY_ID[id]
}
